from urllib.parse import quote_plus

def limpiar_pantalla():
    os.system("cls" if os.name == "nt" else "clear")

def leer_opcion():
    """Lee una opción numérica y evita que una entrada de texto cierre el programa."""
    while True:
        try:
            return int(input().strip())
        except ValueError:
            print("Entrada no válida. Escriba un número para continuar.")




