def mostrar_material_de_estudio(curso, tema):
    """Muestra la ficha de estudio de un tema con un formato uniforme."""
    clave = (curso, tema)
    destino = ASIGNACIONES_MATERIAL.get(clave, clave)
    material = MATERIALES.get(destino)

    if material is None:
        print("Material complementario no especificado en la investigación adjunta.")
        return

    print("Prerrequisitos:")
    print(material["prereq"] or "No especificados en la investigación adjunta.")

    print("\nFuentes de información:")
    if material["sources"]:
        for fuente in material["sources"]:
            print("  - " + fuente)
    else:
        print("  - No especificadas en la investigación adjunta.")

    print("\nPuntos clave:")
    if material["points"]:
        for punto in material["points"]:
            print("  - " + punto)
    else:
        print("  - No especificados en la investigación adjunta.")

    print("\nVideos de apoyo y enlaces:")
    if material["videos"]:
        for video in material["videos"]:
            coincidencia = re.search(r"https?://\S+", video)
            if coincidencia:
                etiqueta = video[:coincidencia.start()].strip(" :")
                print("  - " + (etiqueta or "Video de apoyo"))
                print("    Enlace: " + coincidencia.group(0))
            else:
                enlace = "https://www.youtube.com/results?search_query=" + quote_plus(video)
                print("  - " + video)
                print("    Enlace: " + enlace)
    else:
        print("  - No se proporcionaron videos para este tema.")

def mostrar_temas_complementarios(curso, temas):
    """Abre un submenú con los temas del documento de investigación no incluidos en el menú original."""
    while True:
        limpiar_pantalla()
        print("Has seleccionado los temas complementarios de la investigación adjunta")
        print("Seleccione un tema")
        for numero, tema in enumerate(temas, 1):
            print(f"{numero}---{tema}")
        print(f"{len(temas) + 1}---SALIR")
        opcion = leer_opcion()

        if opcion == len(temas) + 1:
            break
        if 1 <= opcion <= len(temas):
            tema = temas[opcion - 1]
            while True:
                limpiar_pantalla()
                print("Has seleccionado el tema " + tema)
                mostrar_material_de_estudio(curso, tema)
                print("Escriba 1 para salir")
                if leer_opcion() == 1:
                    break
        else:
            print("Opción fuera de rango. Seleccione un número del menú.")



