# Cada tema conserva los prerrequisitos, fuentes y videos de su UDA.
# En "Puntos clave" se muestra la lista completa del bloque al que pertenece.
for _numero_semestre, _areas_semestre in SEMESTRES_DETALLE.items():
    for _area in _areas_semestre:
        for _uda in _area["udas"]:
            _clave_curso = f"SEMESTRE {_numero_semestre} | {_area['name']} | {_uda['name']}"
            for _bloque in _uda["blocks"]:
                for _tema in _bloque["topics"]:
                    _clave_tema = f"{_bloque['name']} | {_tema}"
                    MATERIALES[(_clave_curso, _clave_tema)] = {
                        "prereq": "; ".join(_uda["prereq"]),
                        "sources": list(_uda["sources"]),
                        "points": list(_bloque["topics"]),
                        "videos": list(_uda["videos"]),
                    }


def navegar_semestre(numero_semestre):
    """Navegación jerárquica de quinto y sexto semestre."""
    areas = SEMESTRES_DETALLE[numero_semestre]
    nombre_semestre = "Quinto" if numero_semestre == 5 else "Sexto"

    while True:
        limpiar_pantalla()
        print(f"Has seleccionado el {nombre_semestre} Semestre")
        print("Seleccione el área propedéutica o el área común")
        for indice, area in enumerate(areas, 1):
            print(f"{indice}---{area['name'].upper()}")
        print(f"{len(areas) + 1}---SALIR")
        opcion_area = leer_opcion()

        if opcion_area == len(areas) + 1:
            break
        if not 1 <= opcion_area <= len(areas):
            print("Opción fuera de rango. Seleccione un número del menú.")
            continue

        area = areas[opcion_area - 1]
        udas = area["udas"]

        while True:
            limpiar_pantalla()
            print(f"Has seleccionado {area['name'].upper()}")
            print("Seleccione la UDA")
            for indice, uda in enumerate(udas, 1):
                print(f"{indice}---{uda['name']}")
            print(f"{len(udas) + 1}---SALIR")
            opcion_uda = leer_opcion()

            if opcion_uda == len(udas) + 1:
                break
            if not 1 <= opcion_uda <= len(udas):
                print("Opción fuera de rango. Seleccione un número del menú.")
                continue

            uda = udas[opcion_uda - 1]
            bloques = uda["blocks"]
            clave_curso = f"SEMESTRE {numero_semestre} | {area['name']} | {uda['name']}"

            while True:
                limpiar_pantalla()
                print(f"Has seleccionado: {uda['name']}")
                print("Seleccione un bloque")
                for indice, bloque in enumerate(bloques, 1):
                    print(f"{indice}---{bloque['name']}")
                print(f"{len(bloques) + 1}---SALIR")
                opcion_bloque = leer_opcion()

                if opcion_bloque == len(bloques) + 1:
                    break
                if not 1 <= opcion_bloque <= len(bloques):
                    print("Opción fuera de rango. Seleccione un número del menú.")
                    continue

                bloque = bloques[opcion_bloque - 1]
                temas = bloque["topics"]

                while True:
                    limpiar_pantalla()
                    print(f"Has seleccionado el {bloque['name']}")
                    print("Seleccione un tema")
                    for indice, tema in enumerate(temas, 1):
                        print(f"{indice}---{tema}")
                    print(f"{len(temas) + 1}---SALIR")
                    opcion_tema = leer_opcion()

                    if opcion_tema == len(temas) + 1:
                        break
                    if not 1 <= opcion_tema <= len(temas):
                        print("Opción fuera de rango. Seleccione un número del menú.")
                        continue

                    tema = temas[opcion_tema - 1]
                    clave_tema = f"{bloque['name']} | {tema}"

                    while True:
                        limpiar_pantalla()
                        print("Has seleccionado el tema " + tema)
                        mostrar_material_de_estudio(clave_curso, clave_tema)
                        print("Escriba 1 para salir")
                        if leer_opcion() == 1:
                            break



